INSERT INTO faq (question, answer, keywords) VALUES
('How many leave days do I get per year?', 'Employees are entitled to 24 paid leave days per year. This includes casual leave, sick leave, and earned leave as per company policy.', 'leave,days,annual,vacation,holiday,entitled,per year'),
('What is the notice period for resignation?', 'The notice period is 30 days for all employees. You are required to submit a formal resignation letter to your manager and HR at least 30 days before your last working day.', 'notice,period,resignation,resign,exit,last day,quit,leaving'),
('How do I apply for maternity leave?', 'To apply for maternity leave, submit the maternity leave application form to HR at least 4 weeks in advance. Maternity leave is available for up to 26 weeks as per the Maternity Benefit Act.', 'maternity,leave,apply,form,pregnancy,baby,weeks'),
('What is the work from home policy?', 'Employees may work from home up to 2 days per week, subject to manager approval. You must be available during core hours (10 AM - 4 PM) and ensure proper internet connectivity.', 'work,home,remote,wfh,policy,work from home,hybrid'),
('How do I download my salary slip?', 'You can download your monthly salary slip from the Employee Self Service (ESS) portal at hr.company.com. Login with your employee ID and navigate to Payroll > Salary Slips.', 'salary,slip,payslip,download,portal,pay,payroll'),
('What is the probation period?', 'The standard probation period is 6 months for all new employees. During this period, performance is reviewed monthly. Upon successful completion, you will be confirmed as a permanent employee.', 'probation,period,new employee,confirmation,permanent,joining'),
('How do I apply for sick leave?', 'To apply for sick leave, raise a leave request in the HR portal or inform your manager via email. If absent for more than 2 days, a medical certificate from a registered doctor is required.', 'sick,leave,medical,ill,health,certificate,unwell,doctor'),
('What is the office timing?', 'Standard office hours are 9:00 AM to 6:00 PM, Monday to Friday. Employees are expected to complete 9 hours per day including a 1-hour lunch break. Flexible timing may be available with manager approval.', 'office,timing,hours,work hours,schedule,shift,monday,friday'),
('How do I get my relieving letter?', 'Your relieving letter and experience certificate will be issued on your last working day after completing the full and final settlement process. Please contact HR to initiate your exit formalities.', 'relieving,letter,experience,certificate,exit,full final,settlement,fnf'),
('What are the travel reimbursement rules?', 'Business travel expenses are reimbursed as per company policy. Submit your bills within 7 days of travel using the expense claim form on the HR portal. Cab fares, hotel, and meal expenses are covered up to the approved limits.', 'travel,reimbursement,expense,claim,bills,cab,hotel,meal,allowance'),
('How do I refer someone for a job opening?', 'You can refer candidates for open positions through the Employee Referral Program on the HR portal. If your referral is hired and completes 6 months, you will receive a referral bonus as per the referral policy.', 'refer,referral,job,opening,candidate,bonus,hiring'),
('What is the health insurance policy?', 'All employees and their immediate family (spouse and up to 2 children) are covered under the group health insurance plan. The sum insured is Rs. 5 lakhs per family per year. Contact HR for the insurance card and claim procedures.', 'health,insurance,medical,coverage,claim,family,hospital,cashless'),
('How do I update my personal details?', 'You can update your personal details such as address, emergency contact, and bank details through the Employee Self Service (ESS) portal. For changes to official documents (PAN, Aadhar), submit the supporting documents to HR.', 'update,personal,details,address,bank,contact,information,change'),
('What is the performance review process?', 'Performance reviews are conducted bi-annually — in April and October. You will set goals at the beginning of the review cycle, receive a mid-year check-in, and a final appraisal at the end. Ratings are linked to your annual increment.', 'performance,review,appraisal,increment,rating,goals,KPI,cycle'),
('How do I apply for a loan from the company?', 'Employees who have completed 1 year of service are eligible to apply for a salary advance or personal loan. Submit the loan application form to HR along with the reason and repayment plan. Approval is subject to management discretion.', 'loan,salary advance,personal loan,borrow,repayment,advance');
